class.description:
[DictionaryRecord] is the default mutable record implementation. It stores arbitrary [Variant] values keyed by [StringName] and serializes them with [method @GlobalScope.var_to_bytes].
[codeblock]
var record := DictionaryRecord.new()
record.set_value(&"health", 100)
record.position = Vector2(10, 20)

var bytes := record.serialize()
var copy := DictionaryRecord.new()
copy.deserialize(bytes)
[/codeblock]
